  "implementation": "def solve(case):
    payload = case['payload']
    attempts = payload['attempts']
    max_attempts = payload['max_attempts']
    n = len(attempts)
    if n == 0:
        return {
            'decision': 'continue',
            'next_index': 0,
            'memory_update': {'reflection': 'initial reflection', 'failure_signature': 'initial'}
        }
    last = attempts[-1]
    if last['success']:
        return {
            'decision': 'stop',
            'next_index': n,
            'memory_update': {'reflection': last['reflection'], 'failure_signature': last['failure_signature']}
        }
    if n >= max_attempts:
        return {
            'decision': 'stop',
            'next_index': n,
            'memory_update': {'reflection': last['reflection'], 'failure_signature': last['failure_signature']}
        }
    previous_signatures = [a['failure_signature'] for a in attempts[:-1]]
    if last['failure_signature'] in previous_signatures:
        return {
            'decision': 'stop',
            'next_index': n,
            'memory_update': {'reflection': last['reflection'], 'failure_signature': last['failure_signature']}
        }
    return {
        'decision': 'continue',
        'next_index': n,
        'memory_update': {'reflection': last['reflection'], 'failure_signature': last['failure_signature']}
    }"
